const updateParsed = `-- name: UpdateParsed :execrows
UPDATE messages SET
    alias_id = $2, format = $3, job_number = $4, event_type = $5, description = $6,
    address = $7, locality = $8, grid_ref = $9, call_sign = $10, units = $11,
    extra = $12, parse_failed = $13, address_unsplit = $14, large_event_field = $15, call_signs = $17,
    -- R35h: a format found clears "probably noise"; one taken away marks
    -- nothing (no lock is taken for the rule's other legs here).
    probably_noise = probably_noise AND $3::text IS NULL
WHERE id = $1 AND text = $16
`

type UpdateParsedParams struct {
	ID              int64
	AliasID         *int64
	Format          *string
	JobNumber       *string
	EventType       *string
	Description     *string
	Address         *string
	Locality        *string
	GridRef         *string
	CallSign        *string
	Units           []string
	Extra           []byte
	ParseFailed     bool
	AddressUnsplit  bool
	LargeEventField bool
	Text            string
	CallSigns       []string
}

// A page's parsed fields, written only beside the text they were parsed
// from (P1): 0 rows when its text changed meanwhile (retroactive redaction,
// in its own transaction), and the caller parses it again.
func (q *Queries) UpdateParsed(ctx context.Context, arg UpdateParsedParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateParsed,
		arg.ID,
		arg.AliasID,
		arg.Format,
		arg.JobNumber,
		arg.EventType,
		arg.Description,
		arg.Address,
		arg.Locality,
		arg.GridRef,
		arg.CallSign,
		arg.Units,
		arg.Extra,
		arg.ParseFailed,
		arg.AddressUnsplit,
		arg.LargeEventField,
		arg.Text,
		arg.CallSigns,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

